WITH department_summary AS (SELECT dept_id, SUM(CASE WHEN job_title = 'Intern' THEN 1 ELSE 0 END) AS intern_count, ROUND((100 * SUM(CASE WHEN job_title = 'Analyst' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_analyst FROM employees GROUP BY dept_id) SELECT d.budget, ds.intern_count, ds.pct_analyst FROM departments d INNER JOIN department_summary ds ON d.id = ds.dept_id ORDER BY d.budget;
